import fs from 'fs';
import path from 'path';
import { log } from '../../core/logger.js';
export function writeLocalProperties(projectDirectory) {
    const candidates = [
        process.env.ANDROID_HOME,
        process.env.ANDROID_SDK_ROOT,
        process.env.LOCALAPPDATA ? path.join(process.env.LOCALAPPDATA, 'Android', 'Sdk') : undefined,
        process.env.USERPROFILE ? path.join(process.env.USERPROFILE, 'AppData', 'Local', 'Android', 'Sdk') : undefined,
    ].filter((value) => Boolean(value && value.trim()));
    const sdkPath = candidates.find(candidate => fs.existsSync(candidate));
    if (!sdkPath) {
        log.error('Android SDK not found.');
        log.dim('Set ANDROID_HOME or ANDROID_SDK_ROOT to a valid Android SDK path.');
        log.dim('Example: C:/Users/<you>/AppData/Local/Android/Sdk');
        process.exit(1);
    }
    const normalizedSdkPath = sdkPath.replace(/\\/g, '/');
    const content = `## Generated by WebAPKify - do not commit
sdk.dir=${normalizedSdkPath}`;
    fs.writeFileSync(path.join(projectDirectory, 'local.properties'), content);
    log.dim(`  local.properties (${normalizedSdkPath})`);
}
